const items = $input.all().map(i => i.json);

if (!items.length || !items[0].text) {
  return [{
    json: {
      final_text: "🔍 <b>По вашему запросу подходящих кандидатов не найдено.</b>"
    }
  }];
}

const cards = items.map(item => {
  let text = item.text || "";

  // <br> в перенос строки
  text = text.replace(/<br\s*[\/]?>/gi, '\n');

  // убираем <p>
  text = text.replace(/<\/p>/gi, '\n').replace(/<p>/gi, '');

  return text.trim();
});

const separator = "\n\n" + "—".repeat(22) + "\n\n";

return [{
  json: {
    final_text: cards.join(separator)
  }
}];

let raw = $input.first().json.text || "{}";
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {};
}

const clean = (s) => String(s).replace(/'/g, "''").trim();

const targetRoles = (parsed.target_roles || []).map(clean).filter(Boolean);
const techKeywords = (parsed.tech_keywords || []).map(clean).filter(Boolean);
const location = parsed.location ? clean(parsed.location) : null;

// фильтр: роль в должности или технология в резюме
const roleMatches = targetRoles.map(r => `c.position ILIKE '%${r}%'`);
const techMatches = techKeywords.map(t => `c.resume_text ILIKE '%${t}%'`);

const whereClause = roleMatches.length > 0 
  ? `(${roleMatches.join(" OR ")})` 
  : (techMatches.length > 0 ? `(${techMatches.join(" OR ")})` : "1=1");

// город, если нужен офис
const locCondition = location ? `AND (c.resume_text ILIKE '%${location}%')` : "";

// сортировка: роль в должности +10, каждая технология +1
const roleScore = roleMatches.length > 0
  ? `(CASE WHEN ${roleMatches.join(" OR ")} THEN 10 ELSE 0 END)`
  : "0";

const techScoreParts = ["0"];
techKeywords.forEach(tech => {
  techScoreParts.push(`(CASE WHEN c.resume_text ILIKE '%${tech}%' THEN 1 ELSE 0 END)`);
});
const techScoreFormula = techScoreParts.join(" + ");

const sql = `
SELECT 
    c.id,
    c.fio,
    c.position,
    c.phone,
    c.email,
    c.profiles,
    c.resume_file,
    LEFT(c.resume_text, 20000) AS resume_text
FROM candidates c
WHERE 
    ${whereClause}
    ${locCondition}
ORDER BY (${roleScore} + ${techScoreFormula}) DESC
LIMIT 5;
`.trim();

return [{
  json: { query: sql }
}];
